contract_clause_fact(contrato_ocs_150_2022, clausula_oitava_equilibrio_economico_financeiro_contrato, documentos_revisao, ['atos normativos', 'lista de preço de fabricantes', 'notas fiscais de aquisição de matérias-primas', 'de transporte de mercadorias', 'planilhas de custos unitários'], 'Parágrafo Segundo').
